  });

  slide5.addChart(pres.charts.LINE, [
    {
      name: "Desktop",
      labels: DATA.httpsAdoption.labels,
      values: DATA.httpsAdoption.desktop,
    },
    {
      name: "Mobile",
      labels: DATA.httpsAdoption.labels,
      values: DATA.httpsAdoption.mobile,
    }
  ], {
    x: 5.3, y: 1.9, w: 4.2, h: 3.0,
    chartColors: [COLORS.chartDesktop, COLORS.chartMobile],
    lineSize: 2.5,
    lineSmooth: true,
    showLegend: true,
    legendPos: "b",
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.mutedText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    valAxisTitle: "Adoption %",
    valAxisTitleColor: COLORS.mutedText,
    valAxisTitleFontSize: 10,
    valAxisMinVal: 75,
    valAxisMaxVal: 100,
    showValue: false,
  });

  // Start/end labels
  slide5.addText("~80%", {
    x: 5.3, y: 4.85, w: 0.8, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: COLORS.mutedText, align: "left"
  });
  slide5.addText("2020", {
    x: 5.3, y: 5.05, w: 0.8, h: 0.2,
    fontSize: 9, fontFace: "Calibri", color: COLORS.mutedText, align: "left"
  });
  slide5.addText("99%+", {
    x: 8.7, y: 4.85, w: 0.8, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: COLORS.success, bold: true, align: "right"
  });
  slide5.addText("2025", {
    x: 8.7, y: 5.05, w: 0.8, h: 0.2,
    fontSize: 9, fontFace: "Calibri", color: COLORS.mutedText, align: "right"
  });

  slide5.addText("Source: HTTP Archive State of the Web Report", {
    x: 0.5, y: 5.25, w: 4.5, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: COLORS.mutedText, italic: true
  });

  // ============================================
  // SLIDE 6: HTTP/2 and HTTP/3 Adoption
  // ============================================
  let slide6 = pres.addSlide();
  slide6.background = { color: COLORS.lightBg };

  slide6.addText("HTTP/2 Holds at ~58% While HTTP/3 Support Surges to 40%", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Arial", color: COLORS.darkText, bold: true
  });

  slide6.addText("HTTP/3 is the fastest-growing protocol; measured as support via Alt-Svc headers", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: COLORS.mutedText
  });

  // Stacked/grouped bar chart for current adoption
  slide6.addText("Current Protocol Adoption", {
    x: 0.5, y: 1.35, w: 5.5, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: COLORS.darkText, bold: true, align: "center"
  });

  slide6.addChart(pres.charts.BAR, [
    {
      name: "HTTP/1.1",
      labels: ["Desktop", "Mobile"],
      values: [2.7, 2.4],
    },
    {
      name: "HTTP/2",
      labels: ["Desktop", "Mobile"],
      values: [58.6, 57.6],
    },
    {
      name: "HTTP/3",
      labels: ["Desktop", "Mobile"],
      values: [38.7, 40.0],
    },
  ], {
    x: 0.5, y: 1.7, w: 5.5, h: 2.8,
    barDir: "col",
    chartColors: ["CBD5E1", COLORS.chartDesktop, COLORS.accent],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.mutedText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    valAxisTitle: "Percentage of Requests",
    valAxisTitleColor: COLORS.mutedText,
    valAxisTitleFontSize: 10,
    showLegend: true,
    legendPos: "t",
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.darkText,
    dataLabelFontSize: 10,
    valAxisMaxVal: 100,
  });

  // HTTP/3 growth callout
  slide6.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 1.5, w: 3.3, h: 2.0,
    fill: { color: COLORS.accent }, shadow: makeShadow()
  });
  slide6.addText("HTTP/3 Growth", {
    x: 6.4, y: 1.6, w: 3.1, h: 0.35,
    fontSize: 12, fontFace: "Calibri", color: COLORS.white, bold: true, align: "center"
  });
  slide6.addText("From near-zero", {
    x: 6.4, y: 1.95, w: 3.1, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: COLORS.white, align: "center"
  });
  slide6.addText("38,600%", {
    x: 6.4, y: 2.25, w: 3.1, h: 0.6,
    fontSize: 32, fontFace: "Arial Black", color: COLORS.white, bold: true, align: "center"
  });
  slide6.addText("Desktop", {
    x: 6.4, y: 2.8, w: 1.5, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: COLORS.white, align: "center"
  });
  slide6.addText("5,614%", {
    x: 7.9, y: 2.8, w: 1.5, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: COLORS.white, align: "center"
  });
  slide6.addText("(Desktop)", {
    x: 6.4, y: 3.05, w: 1.5, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: COLORS.secondary, align: "center"
  });
  slide6.addText("(Mobile)", {
    x: 7.9, y: 3.05, w: 1.5, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: COLORS.secondary, align: "center"
  });

  // Key stats cards at bottom
  slide6.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.7, w: 2.9, h: 0.7,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide6.addText("HTTP/2: 58.6% Desktop / 57.6% Mobile", {
    x: 0.6, y: 4.8, w: 2.7, h: 0.5,
    fontSize: 10, fontFace: "Calibri", color: COLORS.darkText, align: "center", valign: "middle"
  });

  slide6.addShape(pres.shapes.RECTANGLE, {
    x: 3.55, y: 4.7, w: 2.9, h: 0.7,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide6.addText("HTTP/3: 38.7% Desktop / 40.0% Mobile", {
    x: 3.65, y: 4.8, w: 2.7, h: 0.5,
    fontSize: 10, fontFace: "Calibri", color: COLORS.darkText, align: "center", valign: "middle"
  });

  // Caveat
  slide6.addText("Note: HTTP Archive measures HTTP/3 support, not actual usage, because fresh Chrome instances default to HTTP/2 on first connection", {
    x: 6.55, y: 4.7, w: 3.1, h: 0.7,
    fontSize: 8, fontFace: "Calibri", color: COLORS.mutedText, italic: true
  });

  slide6.addText("Source: HTTP Archive State of the Web Report", {
    x: 0.5, y: 5.2, w: 5, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: COLORS.mutedText, italic: true
  });

  // ============================================
  // SLIDE 7: Font-Display Adoption
  // ============================================
  let slide7 = pres.addSlide();
  slide7.background = { color: COLORS.lightBg };

  slide7.addText("Font-Display Usage Reaches 42% on Mobile, Up 61% Since 2020", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Arial", color: COLORS.darkText, bold: true
  });

  slide7.addText("CSS font-display property reduces Flash of Invisible Text (FOIT) during font loading", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: COLORS.mutedText
  });

  // Bar chart for font-display adoption
  slide7.addChart(pres.charts.BAR, [
    {
      name: "Desktop",
      labels: DATA.fontDisplay.labels,
      values: DATA.fontDisplay.desktop,
    },
    {
      name: "Mobile",
      labels: DATA.fontDisplay.labels,
      values: DATA.fontDisplay.mobile,
    },
  ], {
    x: 0.5, y: 1.4, w: 6, h: 3.2,
    barDir: "col",
    chartColors: [COLORS.chartDesktop, COLORS.chartMobile],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.mutedText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    valAxisTitle: "Adoption %",
    valAxisTitleColor: COLORS.mutedText,
    valAxisTitleFontSize: 10,
    showLegend: true,
    legendPos: "t",
    showValue: false,
  });

  // Stat callouts on right
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 1.5, w: 2.8, h: 1.2,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 1.5, w: 0.06, h: 1.2, fill: { color: COLORS.chartDesktop }
  });
  slide7.addText("40.1%", {
    x: 6.95, y: 1.55, w: 2.5, h: 0.65,
    fontSize: 32, fontFace: "Arial Black", color: COLORS.chartDesktop, bold: true, align: "center"
  });
  slide7.addText("Desktop", {
    x: 6.95, y: 2.2, w: 2.5, h: 0.35,
    fontSize: 11, fontFace: "Calibri", color: COLORS.mutedText, align: "center"
  });

  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 2.85, w: 2.8, h: 1.2,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 2.85, w: 0.06, h: 1.2, fill: { color: COLORS.chartMobile }
  });
  slide7.addText("42.5%", {
    x: 6.95, y: 2.9, w: 2.5, h: 0.65,
    fontSize: 32, fontFace: "Arial Black", color: COLORS.chartMobile, bold: true, align: "center"
  });
  slide7.addText("Mobile", {
    x: 6.95, y: 3.55, w: 2.5, h: 0.35,
    fontSize: 11, fontFace: "Calibri", color: COLORS.mutedText, align: "center"
  });

  // Growth stats
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 4.2, w: 1.35, h: 0.85,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide7.addText("▲ 14.9%", {
    x: 6.85, y: 4.25, w: 1.25, h: 0.45,
    fontSize: 16, fontFace: "Arial Black", color: COLORS.success, bold: true, align: "center"
  });
  slide7.addText("Desktop", {
    x: 6.85, y: 4.7, w: 1.25, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: COLORS.mutedText, align: "center"
  });

  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 8.25, y: 4.2, w: 1.35, h: 0.85,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide7.addText("▲ 61.0%", {
    x: 8.3, y: 4.25, w: 1.25, h: 0.45,
    fontSize: 16, fontFace: "Arial Black", color: COLORS.success, bold: true, align: "center"
  });
  slide7.addText("Mobile", {
    x: 8.3, y: 4.7, w: 1.25, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: COLORS.mutedText, align: "center"
  });

  // Room for improvement note
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.75, w: 6, h: 0.5,
    fill: { color: COLORS.chartMobile, transparency: 15 }
  });
  slide7.addText("More than half of pages still risk FOIT — significant room for improvement", {
    x: 0.6, y: 4.8, w: 5.8, h: 0.4,
    fontSize: 11, fontFace: "Calibri", color: COLORS.darkText, align: "center", valign: "middle"
  });

  slide7.addText("Source: HTTP Archive State of the Web Report", {
    x: 0.5, y: 5.2, w: 5, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: COLORS.mutedText, italic: true
  });

  // ============================================
  // SLIDE 8: Key Takeaways
  // ============================================
  let slide8 = pres.addSlide();
  slide8.background = { color: COLORS.primary };

  // Decorative accent bar at top
  slide8.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08, fill: { color: COLORS.accent }
  });

  slide8.addText("Key Takeaways", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Arial", color: COLORS.white, bold: true, align: "center"
  });

  slide8.addText("Bigger Pages, Smarter Protocols, Stronger Security", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    fontSize: 16, fontFace: "Calibri", color: COLORS.secondary, align: "center"
  });

  // Takeaway cards in 2x3 grid
  const takeaways = [
    { num: "1", title: "Page Weight Keeps Growing", text: "Median desktop pages now ~2,000 KB (~25% heavier than 2020)" },
    { num: "2", title: "HTTPS Is the New Baseline", text: "At 99%+, unencrypted HTTP is essentially extinct" },
    { num: "3", title: "HTTP/3 Is Fastest Growing", text: "From near-zero to ~40% support in under four years" },
    { num: "4", title: "Connections Down Despite More Requests", text: "Multiplexing cut median TCP connections by 15–27%" },
    { num: "5", title: "Font-Display Still Underused", text: "~40–42% adoption — significant room for FOIT avoidance" },
  ];

  const cardW = 4.3;
  const cardH = 1.0;
  const startX = 0.5;
  const startY = 1.45;
  const gapX = 0.4;
  const gapY = 0.25;

  takeaways.forEach((t, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = startX + col * (cardW + gapX);
    const y = startY + row * (cardH + gapY);

    // Card background
    slide8.addShape(pres.shapes.RECTANGLE, {
      x: x, y: y, w: cardW, h: cardH,
      fill: { color: COLORS.white, transparency: 10 }
    });

    // Number circle
    slide8.addShape(pres.shapes.OVAL, {
      x: x + 0.15, y: y + 0.2, w: 0.5, h: 0.5,
      fill: { color: COLORS.accent }
    });
    slide8.addText(t.num, {
      x: x + 0.15, y: y + 0.2, w: 0.5, h: 0.5,
      fontSize: 16, fontFace: "Arial Black", color: COLORS.white, bold: true, align: "center", valign: "middle"
    });

    // Title and text
    slide8.addText(t.title, {
      x: x + 0.75, y: y + 0.12, w: cardW - 0.9, h: 0.35,
      fontSize: 13, fontFace: "Calibri", color: COLORS.white, bold: true
    });
    slide8.addText(t.text, {
      x: x + 0.75, y: y + 0.45, w: cardW - 0.9, h: 0.45,
      fontSize: 10, fontFace: "Calibri", color: COLORS.secondary
    });
  });

  // Call to action box
  slide8.addShape(pres.shapes.RECTANGLE, {
    x: 1.5, y: 4.75, w: 7, h: 0.6,
    fill: { color: COLORS.accent }
  });
  slide8.addText("Benchmark your own sites against these HTTP Archive baselines", {
    x: 1.6, y: 4.8, w: 6.8, h: 0.5,
    fontSize: 14, fontFace: "Calibri", color: COLORS.white, bold: true, align: "center", valign: "middle"
  });

  // Source
  slide8.addText("Source: HTTP Archive State of the Web Report (httparchive.org)", {
    x: 0.5, y: 5.2, w: 9, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: COLORS.secondary, align: "center"
  });

  // Save the presentation
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

