const pptxgen = require("pptxgenjs");

// Color palette - Midnight Executive for technical/data-forward feel
const COLORS = {
  primary: "1E2761",      // Navy
  secondary: "CADCFC",    // Ice blue
  accent: "0D9488",        // Teal
  accent2: "14B8A6",       // Seafoam
  white: "FFFFFF",
  darkText: "1E293B",
  mutedText: "64748B",
  lightBg: "F8FAFC",
  chartDesktop: "0D9488",  // Teal for desktop
  chartMobile: "F59E0B",   // Amber for mobile
  chartLine: "1E2761",    // Navy for lines
  success: "10B981",       // Green
};

// Data based on source_brief.md
const DATA = {
  // Sample size growth (millions)
  sampleSize: {
    labels: ["Jan 2020", "Jul 2020", "Jan 2021", "Jul 2021", "Jan 2022", "Jul 2022", "Jan 2023", "Jul 2023", "Jan 2024", "Jul 2024", "Jan 2025"],
    desktop: [5.0, 5.5, 6.2, 7.8, 10.5, 15.0, 15.8, 16.0, 16.0, 16.1, 16.0],
    mobile: [3.5, 4.0, 4.8, 5.5, 7.2, 10.0, 11.5, 12.5, 12.5, 12.5, 12.5],
  },
  // Page weight in KB
  pageWeight: {
    labels: ["Jan 2020", "Jan 2021", "Jan 2022", "Jan 2023", "Jan 2024", "Jan 2025"],
    desktop: [1600, 1700, 1800, 1900, 1950, 2000],
    mobile: [1400, 1500, 1600, 1700, 1800, 1900],
    desktop75: [3200, 3400, 3600, 3800, 3950, 4100],
    mobile75: [2800, 3000, 3200, 3400, 3600, 3750],
  },
  // TCP connections per page
  tcpConnections: {
    labels: ["Jan 2020", "Jan 2021", "Jan 2022", "Jan 2023", "Jan 2024", "Jan 2025"],
    desktop: [15, 14.5, 14, 13, 12.5, 12],
    mobile: [15, 14, 13, 12, 11.5, 11],
  },
  // HTTPS adoption %
  httpsAdoption: {
    labels: ["Jan 2020", "Jan 2021", "Jan 2022", "Jan 2023", "Jan 2024", "Jan 2025"],
    desktop: [80, 87, 92, 96, 98.5, 99.2],
    mobile: [79, 86, 91, 95, 98.3, 99.1],
  },
  // HTTP protocol adoption (most recent)
  httpProtocols: {
    labels: ["Desktop", "Mobile"],
    http1: [100 - 58.6 - 38.7, 100 - 57.6 - 40.0],
    http2: [58.6, 57.6],
    http3: [38.7, 40.0],
  },
  // Font-display adoption %
  fontDisplay: {
    labels: ["Jan 2020", "Jan 2021", "Jan 2022", "Jan 2023", "Jan 2024", "Jan 2025"],
    desktop: [35, 36, 37, 38, 39, 40.1],
    mobile: [26.4, 28, 30, 33, 37, 42.5],
  },
};

async function createPresentation() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.title = "State of the Web 2020–2025";
  pres.author = "HTTP Archive";

  // Helper for shadows (fresh object each time)
  const makeShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

  // ============================================
  // SLIDE 1: Title Slide
  // ============================================
  let slide1 = pres.addSlide();
  slide1.background = { color: COLORS.primary };

  // Decorative accent bar at top
  slide1.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08, fill: { color: COLORS.accent }
  });

  // Main title
  slide1.addText("State of the Web 2020–2025", {
    x: 0.5, y: 1.8, w: 9, h: 0.9,
    fontSize: 40, fontFace: "Arial Black", color: COLORS.white, bold: true, align: "center"
  });

  // Subtitle
  slide1.addText("HTTP Archive Trends in Page Weight, Protocols & Security", {
    x: 0.5, y: 2.7, w: 9, h: 0.5,
    fontSize: 20, fontFace: "Calibri", color: COLORS.secondary, align: "center"
  });

  // Source and date range
  slide1.addText([
    { text: "Data Source: HTTP Archive", options: { breakLine: true } },
    { text: "Jan 2020 – Mar 2026", options: {} }
  ], {
    x: 0.5, y: 4.2, w: 9, h: 0.8,
    fontSize: 14, fontFace: "Calibri", color: COLORS.secondary, align: "center"
  });

  // Audience tag
  slide1.addShape(pres.shapes.RECTANGLE, {
    x: 3, y: 5.0, w: 4, h: 0.35,
    fill: { color: COLORS.accent }, line: { color: COLORS.accent }
  });
  slide1.addText("Web Performance Engineers & Front-End Architects", {
    x: 3, y: 5.0, w: 4, h: 0.35,
    fontSize: 10, fontFace: "Calibri", color: COLORS.white, align: "center", valign: "middle"
  });

  // ============================================
  // SLIDE 2: Crawl Sample Size Tripled
  // ============================================
  let slide2 = pres.addSlide();
  slide2.background = { color: COLORS.lightBg };

  // Title
  slide2.addText("Crawl Sample Size Tripled Since 2020", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial", color: COLORS.darkText, bold: true
  });

  // Subtitle
  slide2.addText("Desktop URLs grew from ~5M to 16M; Mobile from ~3.5M to 12.5M", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: COLORS.mutedText
  });

  // Dual-line time-series chart for sample size
  slide2.addChart(pres.charts.LINE, [
    {
      name: "Desktop",
      labels: DATA.sampleSize.labels,
      values: DATA.sampleSize.desktop,
    },
    {
      name: "Mobile",
      labels: DATA.sampleSize.labels,
      values: DATA.sampleSize.mobile,
    }
  ], {
    x: 0.5, y: 1.4, w: 6.5, h: 3.5,
    chartColors: [COLORS.chartDesktop, COLORS.chartMobile],
    lineSize: 2.5,
    lineSmooth: true,
    showLegend: true,
    legendPos: "t",
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.mutedText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    valAxisTitle: "URLs (millions)",
    valAxisTitleColor: COLORS.mutedText,
    valAxisTitleFontSize: 10,
    showValue: false,
  });

  // Key stat callout on right
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 7.3, y: 1.5, w: 2.3, h: 1.3,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 7.3, y: 1.5, w: 0.06, h: 1.3, fill: { color: COLORS.accent }
  });
  slide2.addText("16M", {
    x: 7.4, y: 1.55, w: 2.1, h: 0.7,
    fontSize: 36, fontFace: "Arial Black", color: COLORS.chartDesktop, bold: true, align: "center"
  });
  slide2.addText("Desktop URLs", {
    x: 7.4, y: 2.2, w: 2.1, h: 0.4,
    fontSize: 11, fontFace: "Calibri", color: COLORS.mutedText, align: "center"
  });

  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 7.3, y: 3.0, w: 2.3, h: 1.3,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 7.3, y: 3.0, w: 0.06, h: 1.3, fill: { color: COLORS.chartMobile }
  });
  slide2.addText("12.5M", {
    x: 7.4, y: 3.05, w: 2.1, h: 0.7,
    fontSize: 36, fontFace: "Arial Black", color: COLORS.chartMobile, bold: true, align: "center"
  });
  slide2.addText("Mobile URLs", {
    x: 7.4, y: 3.7, w: 2.1, h: 0.4,
    fontSize: 11, fontFace: "Calibri", color: COLORS.mutedText, align: "center"
  });

  // Source footnote
  slide2.addText("Source: HTTP Archive State of the Web Report", {
    x: 0.5, y: 5.2, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: COLORS.mutedText, italic: true
  });

  // ============================================
  // SLIDE 3: Page Weight Trends
  // ============================================
  let slide3 = pres.addSlide();
  slide3.background = { color: COLORS.lightBg };

  slide3.addText("Median Page Weight Climbs to ~2,000 KB on Desktop", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial", color: COLORS.darkText, bold: true
  });

  slide3.addText("Desktop pages grew ~25% since 2020; 75th percentile exceeds 4,000 KB", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: COLORS.mutedText
  });

  // Line chart for page weight with bands
  slide3.addChart(pres.charts.LINE, [
    {
      name: "Desktop Median",
      labels: DATA.pageWeight.labels,
      values: DATA.pageWeight.desktop,
    },
    {
      name: "Mobile Median",
      labels: DATA.pageWeight.labels,
      values: DATA.pageWeight.mobile,
    },
    {
      name: "Desktop 75th %",
      labels: DATA.pageWeight.labels,
      values: DATA.pageWeight.desktop75,
    },
  ], {
    x: 0.5, y: 1.4, w: 6.5, h: 3.5,
    chartColors: [COLORS.chartDesktop, COLORS.chartMobile, "94A3B8"],
    lineSize: 2.5,
    lineSmooth: true,
    lineDash: [null, null, 4],
    showLegend: true,
    legendPos: "t",
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.mutedText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    valAxisTitle: "Kilobytes",
    valAxisTitleColor: COLORS.mutedText,
    valAxisTitleFontSize: 10,
    showValue: false,
  });

  // Stat callouts
  slide3.addShape(pres.shapes.RECTANGLE, {
    x: 7.3, y: 1.5, w: 2.3, h: 1.1,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide3.addShape(pres.shapes.RECTANGLE, {
    x: 7.3, y: 1.5, w: 0.06, h: 1.1, fill: { color: COLORS.chartDesktop }
  });
  slide3.addText("~2,000 KB", {
    x: 7.4, y: 1.55, w: 2.1, h: 0.55,
    fontSize: 24, fontFace: "Arial Black", color: COLORS.chartDesktop, bold: true, align: "center"
  });
