  });

  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 2.85, w: 2.8, h: 1.2,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 2.85, w: 0.06, h: 1.2, fill: { color: COLORS.chartMobile }
  });
  slide7.addText("42.5%", {
    x: 6.95, y: 2.9, w: 2.5, h: 0.65,
    fontSize: 32, fontFace: "Arial Black", color: COLORS.chartMobile, bold: true, align: "center"
  });
  slide7.addText("Mobile", {
    x: 6.95, y: 3.55, w: 2.5, h: 0.35,
